"""Deterministic ASCAT catalog transition: four source reviews and one scoped upstream family."""
from collections import Counter
import copy,html,json,re
from verify_ascat_workflows import qualified,require

DATA='docs/literature/omics-2023-2026'
META=[DATA+'/'+name for name in('papers.json','tool-inventory.json','summary.json','README.md','WARNINGS.md')]+['tools/literature/reviewed-uses.json','site/literature-review.html','site/literature-warnings.html']
ADMISSION='docs/literature/ascat-catalog-admission'
Q='docs/literature/ascat-validation/QUALIFICATION.json'
GUIDE='docs/ascat-tools.md'
PROGRAM='src/main/java/org/jlinalg/cli/AscatToolsCli.java'
REVIEWED='usage-summary-reviewed; paper-wide-completeness-review-open'
PAPERS={'P111','P129','P143','P146'}
SCOPE='Original ASCAT3.2.0/R4.6.2 and ASCAT2.5.2/R4.0.2 matrix workflows; current original alleleCounter4.3.0 HTS/CRAM and targeted20-normal preparation; explicit correction, genotype prediction, separate or weighted joint segmentation, manual states, purity/ploidy fitting, complete per-locus/segment outputs, QC and plots. Both complete original100-sample examples match direct upstream model objects. Eight qualified captures have complete fresh binary/numerical replay. Java audits complete populations and original segment/objective functions; original R code fits models. One scoped upstream family; existing native helpers receive no extra family credit. Historical author recipes, ascatNgs, imported-estimate execution, whole-package equivalence and full-paper reproduction remain unqualified.'
ACTION='Require COMPLETED.json, inspect WARNINGS.md, OUTPUT-AUDIT.json, original warnings/logs, complete locus/sample states and plots, then use ascat-tools --verify with NEW scratch, exact producing JAR and unchanged permitted Linux runtime. SKIP3 skips dependent analysis when a prerequisite is unavailable/forbidden; supply it only where permitted or retain the skip. FAIL2 admits no complete result: preserve the attempt, correct the named data/runtime/model/QC/resource/cancellation cause and retry NEW paths. High goodness of fit alone did not establish correct recovery in a retained regular-count synthetic experiment. Targeted qualification retained50,136 original min/max warnings from a directly diagnosed zero-homozygote empty-stretch branch; NA stretch bounds are skipped by original code and all25,068 final states match independent truth. Inspect warnings in each actual run; do not assume the same cause. A legacy GC singleton hit a directly reproduced original-source error; an initial tumor-only experiment had no optimum. These failed/unqualified cases are retained without automatic version/source/data repairs. ConstructASCATFiles/PREASCAT are additional supplement-cataloged tools with runtime SKIP3 pending applicable permission; they are outside the current primary counts. MaxQuant remains skipped/pending; Cell Ranger remains excluded. Raw articles, runtimes, processes and cleanup traces remain private; literature HTMLs remain withheld from Pages. Earlier0.4.1 release downloads predate this source-built command.'
CURRENT='250 papers, 451 primary registry labels, 490 providers and 2,731 observations; 1,819 reviewed / 912 pending uses. 171 scoped families: 34 native + 137 upstream, 174 including three existing adapters; 250 primary labels missing, 13 method overlaps and five validated aliases. This admission adds one ASCAT upstream family and four source reviews, with no new primary paper/observation/provider. Two newly identified supplement tools are cataloged separately pending canonical evidence integration;451 is not a discovery ceiling. The full goal remains open.'

def encoded(value):return(json.dumps(value,ensure_ascii=False,indent=2,allow_nan=False)+'\n').encode()

def applied(role):
 result=copy.deepcopy(role);imported=role['paper_id']=='P143';result.update(source_role_review_applied=True,catalog_admitted=True,implementation_available=not imported,implementation_status='RELEASED_ESTIMATE_IMPORT_DISTINCT_FROM_FRESH_FITTING'if imported else'SCOPED_ORIGINAL_WORKFLOWS_AVAILABLE_AUTHOR_RECIPE_PENDING',literal_reported_version=role['literal_package_version_reported_elsewhere'],runtime_analysis_status='NOT_A_REPORTED_FRESH_EXECUTION_ROLE'if imported else'SCOPED_EXPLICIT_ORIGINAL_PROFILES_AVAILABLE',full_source_role_implemented=False,paper_edition_reproduced=False,whole_package_qualified=False,whole_paper_reproduced=False,new_family_credit=0,remaining_scope=role['remaining_scope']+' '+SCOPE);return result

def registry(before):
 result=copy.deepcopy(before);require(len(result)==490,'Provider population changed');rows=[r for r in result if r['id']=='ascat'];require(len(rows)==1 and rows[0]['current_coverage']=='missing','ASCAT provider already admitted/duplicated');rows[0].update(current_coverage='upstream-adapter-validated',existing_source=PROGRAM,coverage_note=SCOPE,integration_family='ascat',family_credit=1);return result

def transition(before,roles,q):
 qualified(q);require(set(before)==set(META),'Predecessor metadata population differs');papers,inventory,summary,ledger=[json.loads(before[META[i]])for i in(0,1,2,5)];require((len(papers),len(inventory),sum(len(p['tools'])for p in papers),len(ledger['reviews']))==(250,451,2731,1815),'Predecessor counts differ')
 selected=roles['roles'];require(len(selected)==4 and{r['paper_id']for r in selected}==PAPERS and all(r['tool_id']=='ascat'for r in selected),'Complete source-role set differs');require(not any(r['tool_id']=='ascat'for r in ledger['reviews']),'ASCAT source review would be duplicated')
 for role in selected:
  paper=next(p for p in papers if p['paper_id']==role['paper_id']);uses=[u for u in paper['tools']if u['tool_id']=='ascat'];require(len(uses)==1 and uses[0]==role['raw_catalog_observation_preserved'],'Raw predecessor observation changed');use=uses[0];scope=role['remaining_scope']+' Available scoped workflow: '+SCOPE
  use.update(use_summary=role['use_summary'],review_status=REVIEWED,evidence_selection='individually-reviewed-source-role',implementation_scope_note=scope,source_role_qualification=applied(role))
  review=dict(pmcid=paper['pmcid'],doi=paper['doi'],tool_id='ascat',evidence_paragraph_sha256=use['evidence_paragraph_sha256'],use_summary=role['use_summary'],implementation_scope_note=scope,usage_context=use['usage_context'],version_reported_near_name=use['version_reported_near_name'],source_role_qualification=applied(role))
  if'supporting_evidence'in use:review['supporting_evidence']=copy.deepcopy(use['supporting_evidence'])
  ledger['reviews'].append(review)
 rows=[r for r in inventory if r['id']=='ascat'];require(len(rows)==1 and rows[0]['implementation_status']==rows[0]['current_coverage']=='missing','ASCAT label already implemented/duplicated');rows[0].update(current_coverage='upstream-adapter-validated',implementation_status='upstream-adapter-validated',existing_source=PROGRAM,implementation_source=PROGRAM,coverage_note=SCOPE,implementation_scope=SCOPE,current_qualification=Q,current_documentation=GUIDE,integration_family='ascat',family_credit=1,source_build_required=True,released_binary_contains_workflow=False,whole_tool_qualified=False,whole_paper_reproduced=False,paper_role_qualification={r['paper_id']:applied(r)for r in selected},runtime_analysis_status='SCOPED_WORKFLOWS_AVAILABLE_EXACT_AUTHOR_AND_OTHER_COMPONENTS_PENDING')
 counts=Counter(r['implementation_status']for r in inventory);summary.update(implementation_status_counts=dict(counts),integration_family_counts=dict(scoped=counts['native-subset-validated']+counts['upstream-adapter-validated'],native=counts['native-subset-validated'],upstream=counts['upstream-adapter-validated'],including_existing_adapters=counts['native-subset-validated']+counts['upstream-adapter-validated']+counts['existing-adapter'],validated_alias_labels_excluded_from_extra_credit=counts['validated-family-alias']),additional_supplementary_tool_candidates=2,supplementary_candidates_catalog='docs/literature/ascat-source-audit-v2/SUPPLEMENTARY-TOOLS.json')
 after=dict(before)
 for name,value in((META[0],papers),(META[1],inventory),(META[2],summary),(META[5],ledger)):
  raw=encoded(value);after[name]=raw.replace(b'\n',b'\r\n')if before[name].count(b'\n')==before[name].count(b'\r\n')else raw
 notice='<aside id="ascat-catalog-notice" style="margin:1rem;padding:1rem;border:2px solid #286d5a;background:#edf8f3;color:#163b30;overflow-wrap:anywhere"><h2>ASCAT matrix, HTS and targeted workflows</h2><p>'+html.escape(CURRENT)+'</p><p>'+html.escape(SCOPE)+'</p><p><strong>Warnings and required actions:</strong> '+html.escape(ACTION)+'</p><p><a href="https://github.com/robbyjo/OmicsMatic/blob/main/'+GUIDE+'">Commands, source profiles, known failures and recovery</a></p></aside>'
 for name in META[6:]:
  page=before[name].decode();require('id="ascat-catalog-notice"'not in page and'id="diffbind-catalog-notice"'in page,'Predecessor report differs')
  if name==META[6]:
   match=re.search(r'(<script id="review-data" type="application/json">)(.*?)(</script>)',page,re.S);require(match and json.loads(match[2])==dict(papers=json.loads(before[META[0]]),tools=json.loads(before[META[1]]),summary=json.loads(before[META[2]])),'Predecessor embedded data differ');payload=json.dumps(dict(papers=papers,tools=inventory,summary=summary),ensure_ascii=False).replace('<','\\u003c');page=page[:match.start(2)]+payload+page[match.end(2):]
   require(page.count('${diffbindVersion(t)}')==page.count('function renderContent(){')==1,'Predecessor role renderer differs')
   helper="function ascatVersion(t){if(t.tool_id!=='ascat'||!t.source_role_qualification)return diffbindVersion(t);const q=t.source_role_qualification;return '<br><span style=\"overflow-wrap:anywhere\">Reported core ASCAT: '+esc(q.literal_reported_version??'not reported')+'; role: '+esc(q.role_kind)+'; exact author recipe pending. '+esc(q.remaining_scope)+'</span>';}\n"
   page=page.replace('${diffbindVersion(t)}','${ascatVersion(t)}',1).replace('function renderContent(){',helper+'function renderContent(){',1)
  body=re.search(r'<body[^>]*>',page,re.I);marker=page.find('<site-header ',body.end());require(marker>=body.end(),'Report boundary changed');after[name]=(page[:body.end()]+notice+'<details id="ascat-prior-catalog"><summary>Before ASCAT admission (historical)</summary>'+page[body.end():marker]+'</details>'+page[marker:]).encode()
 prefix=('# Current ASCAT catalog checkpoint\n\n'+CURRENT+'\n\n'+SCOPE+'\n\n**Warnings and required actions:** '+ACTION+'\n\nSee [ASCAT guide](../../ascat-tools.md) and [supplement source audit](../ascat-source-audit-v2/README.md).\n\n---\n\nEarlier checkpoints below are historical.\n\n').encode()
 for name in META[3:5]:after[name]=prefix+before[name]
 return after

def check(before,after,roles,q):
 require(after==transition(before,roles,q),'Deterministic ASCAT transition differs');old,new=json.loads(before[META[0]]),json.loads(after[META[0]])
 for left,right in zip(old,new,strict=True):
  require({k:v for k,v in left.items()if k!='tools'}=={k:v for k,v in right.items()if k!='tools'},'Paper identity changed');require([u for u in left['tools']if u['tool_id']!='ascat']==[u for u in right['tools']if u['tool_id']!='ascat'],'Unrelated observation changed')
 a,b=json.loads(before[META[1]]),json.loads(after[META[1]]);require([r for r in a if r['id']!='ascat']==[r for r in b if r['id']!='ascat'],'Unrelated inventory changed');prior=json.loads(before[META[5]])['reviews'];reviews=json.loads(after[META[5]])['reviews'];require(len(reviews)==len({(r['pmcid'],r['tool_id'])for r in reviews})==1819,'Wrong review count/duplicate');require([r for r in reviews if r['tool_id']!='ascat']==prior,'Unrelated review changed')
 marked={(p['pmcid'],u['tool_id'])for p in new for u in p['tools']if u['review_status']in(REVIEWED,'individually-reviewed-primary-source-roles; whole-paper-method-review-open')};require(marked=={(r['pmcid'],r['tool_id'])for r in reviews},'Review markers/ledger differ');counts=Counter(r['implementation_status']for r in b);require((counts['native-subset-validated'],counts['upstream-adapter-validated'],counts['missing'],counts['method-overlap'],counts['validated-family-alias'])==(34,137,250,13,5),'Wrong family credit')
 return dict(papers=250,primary_labels=451,provider_definitions=490,observations=2731,reviewed_uses=1819,pending_uses=912,scoped_families=171,native=34,upstream=137,including_existing_adapters=174,missing_primary_labels=250,additional_supplementary_tool_candidates=2,method_overlap=13,validated_alias_labels=5,new_upstream_family_credit=1,new_native_family_credit=0,new_source_reviews=4,new_primary_papers_or_observations_or_providers=0,unchanged_unrelated_inventory_rows=450,unchanged_unrelated_observations=2727,unchanged_unrelated_reviews=1815,whole_package_qualified=False,full_author_roles_implemented=False,whole_paper_reproduced=False,whole_goal_complete=False)
